import { describe, it, expect, vi, beforeEach } from 'vitest';
import { buildServer } from '../server';

const prismaMock = vi.hoisted(() => ({
  endpoint: { create: vi.fn(), findUnique: vi.fn(), update: vi.fn() },
  delivery: { findMany: vi.fn(), findUnique: vi.fn(), findUniqueOrThrow: vi.fn(), update: vi.fn() },
}));

vi.mock('@tallyhook/shared', async () => {
  const schemas = await vi.importActual<typeof import('@tallyhook/shared/src/schemas')>(
    '@tallyhook/shared/src/schemas',
  );
  return { ...schemas, prisma: prismaMock, logger: false };
});

vi.mock('../queue', () => ({ deliveryQueue: { add: vi.fn() }, redis: {} }));

const rows = (n: number) => Array.from({ length: n }, (_, i) => ({ id: `dl_${i + 1}` }));

describe('GET /v1/endpoints/:id/deliveries', () => {
  beforeEach(() => vi.clearAllMocks());

  it('returns nextCursor when there is another page', async () => {
    prismaMock.delivery.findMany.mockResolvedValue(rows(3));
    const app = buildServer();
    const res = await app.inject({ method: 'GET', url: '/v1/endpoints/ep_1/deliveries?limit=2' });
    expect(res.json()).toEqual({ items: rows(2), nextCursor: 'dl_2' });
    expect(prismaMock.delivery.findMany.mock.calls[0][0].take).toBe(3);
  });

  it('passes the cursor through and ends with a null cursor', async () => {
    prismaMock.delivery.findMany.mockResolvedValue(rows(1));
    const app = buildServer();
    const res = await app.inject({
      method: 'GET',
      url: '/v1/endpoints/ep_1/deliveries?limit=2&cursor=dl_2',
    });
    expect(res.json().nextCursor).toBeNull();
    expect(prismaMock.delivery.findMany.mock.calls[0][0]).toMatchObject({
      cursor: { id: 'dl_2' },
      skip: 1,
    });
  });
});

